// \p{Nd} support + digit-run trick
const isNd = (cp) => /\p{Nd}/u.test(String.fromCodePoint(cp));
function digitVal(cp){
  if(!isNd(cp)) return -1;
  let start = cp;
  while(start > 0 && isNd(start-1)) start--;
  return (cp - start) % 10;
}
for (const [name,cp] of [['ascii5',0x35],['arabic-indic5',0x665],['extarab5',0x6F5],['deva5',0x96B],['fullwidth5',0xFF15],['thai5',0xE55],['mathbold5',0x1D7D3],['mathsans7',0x1D7E9],['osmanya5',0x104A5],['nko3',0x7C3]])
  console.log(name, cp.toString(16), digitVal(cp));
console.log('cat tests:', /\p{Cn}/u.test('͸'), /\p{Cf}/u.test('​'), /\p{Zs}/u.test(' '));
console.log('superscript1', digitVal(0xb9), 'circled1', digitVal(0x2460), 'roman', digitVal(0x2160), 'half', digitVal(0xbd));
