/**
 * Character-level helpers that reproduce the CPython character classification
 * rules the original program depends on.
 *
 * The Python source relies on three of them, indirectly:
 *   - `int(str)` skips *Python* whitespace at both ends of its argument.
 *   - `int(str)` accepts any Unicode decimal digit, not just ASCII 0-9.
 *   - `repr()` of a str keeps printable characters verbatim and escapes the rest.
 *
 * Everything here works on Unicode code points (numbers), never on byte
 * containers, so the module has no dependency on binary buffer types.
 */

/**
 * The exact set of code points for which CPython's `Py_UNICODE_ISSPACE()` is
 * true.  This is what `int()` strips (via `PyLong_FromUnicodeObject`), and it
 * is deliberately *not* the same as JavaScript's `\s`: U+200B ZERO WIDTH SPACE
 * is not whitespace to Python, while U+001C..U+001F are.
 */
const PY_WHITESPACE = new Set([
  0x09, // \t  HORIZONTAL TAB
  0x0a, // \n  LINE FEED
  0x0b, // \v  VERTICAL TAB
  0x0c, // \f  FORM FEED
  0x0d, // \r  CARRIAGE RETURN
  0x1c, //     FILE SEPARATOR
  0x1d, //     GROUP SEPARATOR
  0x1e, //     RECORD SEPARATOR
  0x1f, //     UNIT SEPARATOR
  0x20, //     SPACE
  0x85, //     NEXT LINE
  0xa0, //     NO-BREAK SPACE
  0x1680, //   OGHAM SPACE MARK
  0x2000, //   EN QUAD
  0x2001, //   EM QUAD
  0x2002, //   EN SPACE
  0x2003, //   EM SPACE
  0x2004, //   THREE-PER-EM SPACE
  0x2005, //   FOUR-PER-EM SPACE
  0x2006, //   SIX-PER-EM SPACE
  0x2007, //   FIGURE SPACE
  0x2008, //   PUNCTUATION SPACE
  0x2009, //   THIN SPACE
  0x200a, //   HAIR SPACE
  0x2028, //   LINE SEPARATOR
  0x2029, //   PARAGRAPH SEPARATOR
  0x202f, //   NARROW NO-BREAK SPACE
  0x205f, //   MEDIUM MATHEMATICAL SPACE
  0x3000, //   IDEOGRAPHIC SPACE
]);

/** True when `codePoint` is whitespace by CPython's definition. */
export function isPyWhitespace(codePoint) {
  return PY_WHITESPACE.has(codePoint);
}

const ND_RE = /^\p{Nd}$/u;
const ndCache = new Map();

/** True when `codePoint` is in Unicode general category Nd (decimal digit). */
function isDecimalDigit(codePoint) {
  let cached = ndCache.get(codePoint);
  if (cached === undefined) {
    cached = codePoint >= 0 && codePoint <= 0x10ffff && ND_RE.test(String.fromCodePoint(codePoint));
    ndCache.set(codePoint, cached);
  }
  return cached;
}

/**
 * Numeric value 0-9 of a Unicode decimal digit, or -1 when `codePoint` is not
 * a decimal digit.
 *
 * Category Nd is laid out as contiguous, ten-aligned runs of `0..9` per script
 * (U+0660..U+0669 for Arabic-Indic, U+FF10..U+FF19 for fullwidth, and so on).
 * Several runs may sit back to back — the mathematical alphanumeric digits at
 * U+1D7CE..U+1D7FF are five runs in a row — so the value is the offset from
 * the start of the surrounding run, taken modulo ten.
 *
 * Characters that merely *look* numeric but live in other categories (No: '¹',
 * '½', '①'; Nl: 'Ⅰ') are rejected here, exactly as `int()` rejects them.
 */
export function decimalDigitValue(codePoint) {
  if (!isDecimalDigit(codePoint)) return -1;
  let runStart = codePoint;
  while (runStart > 0 && isDecimalDigit(runStart - 1)) runStart -= 1;
  return (codePoint - runStart) % 10;
}

/** True for the ASCII underscore, the digit separator accepted by `int()`. */
export function isUnderscore(codePoint) {
  return codePoint === 0x5f;
}

/**
 * Categories CPython treats as non-printable in `repr()`:
 * everything in Cc, Cf, Cs, Co, Cn, Zl, Zp and Zs — with the single exception
 * of U+0020 SPACE, which is printable.
 */
const NONPRINTABLE_RE = /^[\p{Cc}\p{Cf}\p{Cs}\p{Co}\p{Cn}\p{Zl}\p{Zp}\p{Zs}]$/u;

/** True when `repr()` would keep this code point verbatim. */
export function isPyPrintable(codePoint) {
  if (codePoint === 0x20) return true;
  return !NONPRINTABLE_RE.test(String.fromCodePoint(codePoint));
}

/** Code points of a JS string, iterating by code point (surrogate-aware). */
export function codePointsOf(text) {
  const out = [];
  for (const ch of text) out.push(ch.codePointAt(0));
  return out;
}

