/**
 * `ByteString` — an immutable sequence of byte values that stands in for
 * Python's built-in `bytes` type.
 *
 * The bencode codec deals in octets, so it needs a byte container.  This one is
 * backed by a plain JavaScript `Array` of integers in [0, 255] and a lazily
 * built latin-1 string; no binary buffer types are involved anywhere in this
 * project.  Every operation the codec and the printer need — concatenation,
 * slicing, indexing, comparison, UTF-8 transcoding — is implemented here in
 * terms of ordinary numbers and strings.
 */

import { codePointsOf } from './chars.mjs';

/** Thrown when a value cannot be interpreted as a byte sequence. */
export class ByteError extends Error {
  constructor(message) {
    super(message);
    this.name = 'ByteError';
  }
}

function assertByte(value) {
  if (!Number.isInteger(value) || value < 0 || value > 0xff) {
    throw new ByteError(`byte must be in range(0, 256), got ${String(value)}`);
  }
  return value;
}

export class ByteString {
  /**
   * @param {number[]} codes Byte values; taken over as-is, so callers must not
   *   retain a reference to a mutable array they still intend to change.
   */
  constructor(codes = []) {
    this._codes = codes;
    this._latin1 = null;
    Object.freeze(this._codes);
    Object.seal(this);
  }

  /** Build from anything iterable that yields byte values. */
  static fromCodes(iterable) {
    const codes = [];
    for (const value of iterable) codes.push(assertByte(value));
    return new ByteString(codes);
  }

  /** Build from a string whose code units are all <= 0xFF (latin-1 / binary). */
  static fromLatin1(text) {
    const codes = new Array(text.length);
    for (let i = 0; i < text.length; i += 1) {
      const unit = text.charCodeAt(i);
      if (unit > 0xff) {
        throw new ByteError(`character U+${unit.toString(16).toUpperCase()} is not a latin-1 byte`);
      }
      codes[i] = unit;
    }
    const bytes = new ByteString(codes);
    bytes._latin1 = text;
    return bytes;
  }

  /** Build from a string interpreted as ASCII (rejects anything above 0x7F). */
  static fromAscii(text) {
    const codes = new Array(text.length);
    for (let i = 0; i < text.length; i += 1) {
      const unit = text.charCodeAt(i);
      if (unit > 0x7f) throw new ByteError('non-ASCII character in ASCII literal');
      codes[i] = unit;
    }
    return new ByteString(codes);
  }

  /**
   * Build from a string encoded as UTF-8 — the encoding Python's
   * `str.encode()` uses by default, and therefore what `bencoder.encode()`
   * applies to `str` values.  Encoded by hand from code points, so no
   * text-encoder object is needed.
   */
  static fromUtf8(text) {
    const codes = [];
    for (const codePoint of codePointsOf(text)) {
      if (codePoint < 0x80) {
        codes.push(codePoint);
      } else if (codePoint < 0x800) {
        codes.push(0xc0 | (codePoint >> 6), 0x80 | (codePoint & 0x3f));
      } else if (codePoint < 0x10000) {
        codes.push(
          0xe0 | (codePoint >> 12),
          0x80 | ((codePoint >> 6) & 0x3f),
          0x80 | (codePoint & 0x3f),
        );
      } else {
        codes.push(
          0xf0 | (codePoint >> 18),
          0x80 | ((codePoint >> 12) & 0x3f),
          0x80 | ((codePoint >> 6) & 0x3f),
          0x80 | (codePoint & 0x3f),
        );
      }
    }
    return new ByteString(codes);
  }

  /** Concatenate any number of `ByteString`s into a new one. */
  static concat(parts) {
    const codes = [];
    for (const part of parts) {
      for (let i = 0; i < part._codes.length; i += 1) codes.push(part._codes[i]);
    }
    return new ByteString(codes);
  }

  /** Coerce a `ByteString`, latin-1 string or byte array into a `ByteString`. */
  static coerce(value) {
    if (value instanceof ByteString) return value;
    if (typeof value === 'string') return ByteString.fromLatin1(value);
    if (Array.isArray(value)) return ByteString.fromCodes(value);
    throw new ByteError('value cannot be interpreted as a byte sequence');
  }

  get length() {
    return this._codes.length;
  }

  /** Byte value at `index`, or `undefined` when out of range. */
  codeAt(index) {
    return this._codes[index];
  }

  /** Sub-sequence in `[start, end)`, following `Array.prototype.slice`. */
  slice(start, end) {
    return new ByteString(this._codes.slice(start, end));
  }

  /** This byte string followed by `other`. */
  concat(other) {
    return ByteString.concat([this, other]);
  }

  equals(other) {
    if (!(other instanceof ByteString)) return false;
    if (other._codes.length !== this._codes.length) return false;
    for (let i = 0; i < this._codes.length; i += 1) {
      if (this._codes[i] !== other._codes[i]) return false;
    }
    return true;
  }

  /**
   * Lexicographic comparison of raw byte values — the ordering Python uses for
   * `bytes`, and hence the ordering `bencoder` needs for dict keys.
   */
  compare(other) {
    const limit = Math.min(this._codes.length, other._codes.length);
    for (let i = 0; i < limit; i += 1) {
      if (this._codes[i] !== other._codes[i]) return this._codes[i] < other._codes[i] ? -1 : 1;
    }
    if (this._codes.length === other._codes.length) return 0;
    return this._codes.length < other._codes.length ? -1 : 1;
  }

  /** A string with one code unit per byte (latin-1 round trip). */
  toLatin1() {
    if (this._latin1 === null) {
      let text = '';
      // Chunked so very long byte strings do not blow the argument limit.
      const CHUNK = 4096;
      for (let i = 0; i < this._codes.length; i += CHUNK) {
        text += String.fromCharCode.apply(null, this._codes.slice(i, i + CHUNK));
      }
      this._latin1 = text;
    }
    return this._latin1;
  }

  /** A copy of the byte values as a plain array. */
  toCodes() {
    return this._codes.slice();
  }

  *[Symbol.iterator]() {
    for (let i = 0; i < this._codes.length; i += 1) yield this._codes[i];
  }
}

/** The empty byte string, `b''`. */
export const EMPTY_BYTES = new ByteString([]);

/** Shorthand for `ByteString.fromAscii()`, for building codec literals. */
export function ascii(text) {
  return ByteString.fromAscii(text);
}

