/**
 * `int(str)` with CPython's exact accept/reject semantics, base 10.
 *
 * Mirrors `PyLong_FromUnicodeObject` for base 10:
 *
 *     value  ::=  ws* sign? digits ws*
 *     sign   ::=  '+' | '-'
 *     digits ::=  digit ( '_'? digit )*
 *
 * where `ws` is Python whitespace (see `chars.mjs`, wider than JS `\s` in some
 * places and narrower in others) and `digit` is *any* Unicode decimal digit,
 * so '٥', '५' and '５' all parse — and may even be mixed inside one literal.
 *
 * Three details that a naive `Number()`/`BigInt()` port gets wrong and that
 * this implementation gets right:
 *   - underscores may only sit singly *between* digits: `1_000` parses,
 *     `1__0`, `_10`, `10_` and `-_10` do not;
 *   - whitespace may surround the literal but must not separate the sign from
 *     the digits, so `' -5 '` parses while `'- 5'` does not;
 *   - the result is unbounded, so it is produced as a `BigInt`.
 */

import { decimalDigitValue, isPyWhitespace, isUnderscore, codePointsOf } from './chars.mjs';

/** Raised for input `int()` would reject, carrying CPython's message text. */
export class PyValueError extends Error {
  constructor(message) {
