 *     print(decoded)           ->  reprList(...)    ->  [10, -10, 0, -100]
 *     print(encoded_negative)  ->  reprBytes(...)   ->  b'i-10e'
 *     print(encoded_zero)      ->  reprBytes(...)   ->  b'i0e'
 */

import { ByteString } from './bytes.mjs';
import { isPyPrintable, codePointsOf } from './chars.mjs';

const SINGLE_QUOTE = 0x27;
const DOUBLE_QUOTE = 0x22;
const BACKSLASH = 0x5c;

function hex2(value) {
  return value.toString(16).padStart(2, '0');
}

/**
 * `repr()` of a `bytes` object.
 *
 * CPython's `bytes_repr`: the literal is single-quoted unless it contains a
 * single quote and no double quote, in which case double quotes are used and
 * the single quote needs no escape.  Inside, a backslash and the active quote
 * are backslash-escaped, tab/newline/return get their short escapes, and every
 * byte outside printable ASCII (below 0x20, or 0x7F and above) becomes `\xHH`
 * with lowercase hex digits.
