export function reprBytes(value) {
  const bytes = ByteString.coerce(value);
  let hasSingle = false;
  let hasDouble = false;
  for (const code of bytes) {
    if (code === SINGLE_QUOTE) hasSingle = true;
    else if (code === DOUBLE_QUOTE) hasDouble = true;
  }
  const quote = hasSingle && !hasDouble ? DOUBLE_QUOTE : SINGLE_QUOTE;
  const quoteChar = String.fromCharCode(quote);

  let body = '';
  for (const code of bytes) {
    if (code === quote || code === BACKSLASH) body += `\\${String.fromCharCode(code)}`;
    else if (code === 0x09) body += '\\t';
    else if (code === 0x0a) body += '\\n';
    else if (code === 0x0d) body += '\\r';
    else if (code < 0x20 || code >= 0x7f) body += `\\x${hex2(code)}`;
    else body += String.fromCharCode(code);
  }
  return `b${quoteChar}${body}${quoteChar}`;
}

