 * `repr()` of a `str`.
 *
 * Same quote choice as `bytes`, but non-ASCII printable characters are kept
 * verbatim (Python 3 reprs are Unicode) and only non-printable code points are
 * escaped, as `\xHH`, `\uXXXX` or `\UXXXXXXXX` by magnitude.  Used for the
 * `argparse` diagnostics that quote a rejected value.
 */
export function reprStr(text) {
  const points = codePointsOf(text);
  const hasSingle = points.includes(SINGLE_QUOTE);
  const hasDouble = points.includes(DOUBLE_QUOTE);
  const quote = hasSingle && !hasDouble ? DOUBLE_QUOTE : SINGLE_QUOTE;
  const quoteChar = String.fromCharCode(quote);

  let body = '';
  for (const point of points) {
    if (point === quote || point === BACKSLASH) body += `\\${String.fromCodePoint(point)}`;
    else if (point === 0x09) body += '\\t';
    else if (point === 0x0a) body += '\\n';
    else if (point === 0x0d) body += '\\r';
    else if (isPyPrintable(point)) body += String.fromCodePoint(point);
    else if (point < 0x100) body += `\\x${hex2(point)}`;
    else if (point < 0x10000) body += `\\u${point.toString(16).padStart(4, '0')}`;
