/**
 * Python's `print()` and the process-exit convention `sys.exit()` uses.
 *
 * Writes go straight to the standard streams as text, so the four output lines
 * land byte for byte where CPython puts them: everything from `print()` on
 * stdout, everything `argparse` emits on failure on stderr, each terminated by
 * a single `\n` (CPython does not translate line endings on these streams for
 * the outputs this program produces).
 */

import { pyStr } from './repr.mjs';

/** `print(*values, sep=' ', end='\n')`, writing to stdout. */
export function pyPrint(...values) {
  writeOut(`${values.map((value) => pyStr(value)).join(' ')}\n`);
}

/** Raw text to stdout, no trailing newline added. */
export function writeOut(text) {
  process.stdout.write(text);
}

/** Raw text to stderr, no trailing newline added — `sys.stderr.write()`. */
export function writeErr(text) {
  process.stderr.write(text);
}

/**
 * The exception `sys.exit()` raises.
 *
 * Thrown rather than exiting on the spot so the entry point can unwind to the
 * top and let Node flush both streams before the process ends; calling
 * `process.exit()` mid-write can truncate piped output.
 */
export class SystemExit extends Error {
  constructor(code = 0) {
    super(`SystemExit: ${code}`);
    this.name = 'SystemExit';
    this.code = code;
  }
}

