/**
 * bencode serialisation — the `bencoder.encode()` half.
 *
 * The four bencode types and their wire forms:
 *
 *     integer     i<decimal>e            42     -> i42e     -7 -> i-7e
 *     byte string <length>:<bytes>       b'ab'  -> 2:ab
 *     list        l<item>...e            [1, 2] -> li1ei2ee
 *     dictionary  d<key><value>...e      keys are byte strings, sorted
 *
 * Integers are unbounded in Python, so they are carried as `BigInt` here and
 * rendered with plain decimal digits — no exponent form, no separators, and
 * `-0` collapses to `0`, which is why `encode(-a)` prints `i0e` when `a` is 0.
 */

import { ByteString, ascii } from '../python/bytes.mjs';
import { BencodeEncodeError } from './errors.mjs';

const LIST_START = ascii('l');
const DICT_START = ascii('d');
const CONTAINER_END = ascii('e');

/** `i<n>e` for an integer. */
export function encodeInt(value) {
  return ascii(`i${BigInt(value).toString(10)}e`);
}

/** `<len>:<bytes>` for a byte string. */
export function encodeBytes(value) {
  const bytes = ByteString.coerce(value);
  return ascii(`${bytes.length}:`).concat(bytes);
}

/** A `str` is encoded as its UTF-8 bytes, exactly like `bytes`. */
export function encodeString(text) {
  return encodeBytes(ByteString.fromUtf8(text));
}

/** `l<item>...e` for a list or tuple. */
export function encodeList(items) {
  const parts = [LIST_START];
  for (const item of items) parts.push(encode(item));
  parts.push(CONTAINER_END);
  return ByteString.concat(parts);
}

/**
 * `d<key><value>...e` for a dictionary.
 *
 * Keys are coerced to byte strings and emitted in ascending byte order, as
 * the bencode format requires for a canonical encoding.
 */
export function encodeDict(entries) {
  const pairs = [];
  for (const [key, value] of entries) {
    const keyBytes = typeof key === 'string' ? ByteString.fromUtf8(key) : ByteString.coerce(key);
    pairs.push([keyBytes, value]);
  }
  pairs.sort((left, right) => left[0].compare(right[0]));

  const parts = [DICT_START];
  for (const [keyBytes, value] of pairs) {
    parts.push(encodeBytes(keyBytes), encode(value));
  }
  parts.push(CONTAINER_END);
  return ByteString.concat(parts);
}

/**
 * Encode any supported value into a `ByteString`.
 *
 * Accepts `BigInt`, safe integer `number`, `boolean` (Python's `bool` is an
 * `int`, so `true` encodes as `i1e`), `ByteString`, `string`, `Array` and
 * `Map`/plain object for dictionaries.
 */
export function encode(value) {
  if (typeof value === 'bigint') return encodeInt(value);
  if (typeof value === 'boolean') return encodeInt(value ? 1n : 0n);
  if (typeof value === 'number') {
    if (!Number.isInteger(value)) {
      throw new BencodeEncodeError('cannot encode a non-integral number');
    }
    if (!Number.isSafeInteger(value)) {
      throw new BencodeEncodeError('integer beyond safe range; pass a BigInt instead');
    }
    return encodeInt(BigInt(value));
  }
  if (value instanceof ByteString) return encodeBytes(value);
  if (typeof value === 'string') return encodeString(value);
  if (Array.isArray(value)) return encodeList(value);
  if (value instanceof Map) return encodeDict(value.entries());
  if (value !== null && typeof value === 'object') return encodeDict(Object.entries(value));
  throw new BencodeEncodeError('value is not bencodable');
}

