  return ascii(`i${BigInt(value).toString(10)}e`);
}

/** `<len>:<bytes>` for a byte string. */
export function encodeBytes(value) {
  const bytes = ByteString.coerce(value);
  return ascii(`${bytes.length}:`).concat(bytes);
}

/** A `str` is encoded as its UTF-8 bytes, exactly like `bytes`. */
export function encodeString(text) {
  return encodeBytes(ByteString.fromUtf8(text));
}

/** `l<item>...e` for a list or tuple. */
export function encodeList(items) {
  const parts = [LIST_START];
  for (const item of items) parts.push(encode(item));
  parts.push(CONTAINER_END);
  return ByteString.concat(parts);
}

/**
 * `d<key><value>...e` for a dictionary.
 *
 * Keys are coerced to byte strings and emitted in ascending byte order, as
 * the bencode format requires for a canonical encoding.
 */
export function encodeDict(entries) {
  const pairs = [];
  for (const [key, value] of entries) {
    const keyBytes = typeof key === 'string' ? ByteString.fromUtf8(key) : ByteString.coerce(key);
    pairs.push([keyBytes, value]);
  }
  pairs.sort((left, right) => left[0].compare(right[0]));

  const parts = [DICT_START];
  for (const [keyBytes, value] of pairs) {
    parts.push(encodeBytes(keyBytes), encode(value));
  }
  parts.push(CONTAINER_END);
