 * leading zero in a length or a multi-digit integer is rejected, `i-0e` is
 * rejected, and trailing bytes after one complete value are an error rather
 * than being silently ignored.
 */

import { ByteString } from '../python/bytes.mjs';
import { tryPyInt } from '../python/int.mjs';
import { BencodeDecodeError } from './errors.mjs';

const CODE_i = 0x69;
const CODE_l = 0x6c;
const CODE_d = 0x64;
const CODE_e = 0x65;
const CODE_MINUS = 0x2d;
const CODE_ZERO = 0x30;
const CODE_NINE = 0x39;
const CODE_COLON = 0x3a;

function findCode(bytes, code, from) {
  for (let i = from; i < bytes.length; i += 1) {
    if (bytes.codeAt(i) === code) return i;
  }
  return -1;
}

/** Parse the integer literal in `[start, end)` as a Python `int` would. */
function literalToInt(bytes, start, end) {
  const value = tryPyInt(bytes.slice(start, end).toLatin1());
  if (value === null) throw new BencodeDecodeError('malformed number in bencoded value');
  return value;
}

/** `i<n>e` at `index`; returns the value and the position just past the `e`. */
function decodeInt(bytes, index) {
  const terminator = findCode(bytes, CODE_e, index + 1);
  if (terminator < 0) throw new BencodeDecodeError('unterminated integer in bencoded value');
  const first = bytes.codeAt(index + 1);
  if (first === CODE_MINUS) {
    if (bytes.codeAt(index + 2) === CODE_ZERO) {
      throw new BencodeDecodeError('negative zero is not a valid bencoded integer');
    }
  } else if (first === CODE_ZERO && terminator !== index + 2) {
    throw new BencodeDecodeError('leading zero is not a valid bencoded integer');
  }
  return [literalToInt(bytes, index + 1, terminator), terminator + 1];
}

/** `<len>:<bytes>` at `index`; returns the byte string and the next position. */
function decodeByteString(bytes, index) {
  const colon = findCode(bytes, CODE_COLON, index);
  if (colon < 0) throw new BencodeDecodeError('missing length delimiter in bencoded value');
  if (bytes.codeAt(index) === CODE_ZERO && colon !== index + 1) {
    throw new BencodeDecodeError('leading zero is not a valid bencoded length');
