function decodeList(bytes, index) {
  const items = [];
  let cursor = index + 1;
  while (true) {
    if (cursor >= bytes.length) throw new BencodeDecodeError('unterminated list in bencoded value');
    if (bytes.codeAt(cursor) === CODE_e) return [items, cursor + 1];
    const [value, next] = decodeValue(bytes, cursor);
    items.push(value);
    cursor = next;
  }
