function decodeDict(bytes, index) {
  const entries = new Map();
  let cursor = index + 1;
  while (true) {
    if (cursor >= bytes.length) {
      throw new BencodeDecodeError('unterminated dictionary in bencoded value');
    }
    if (bytes.codeAt(cursor) === CODE_e) return [entries, cursor + 1];
    const [key, afterKey] = decodeByteString(bytes, cursor);
    const [value, afterValue] = decodeValue(bytes, afterKey);
    entries.set(key, value);
    cursor = afterValue;
  }
