/** Decode one value starting at `index`; returns `[value, nextIndex]`. */
function decodeValue(bytes, index) {
  if (index >= bytes.length) throw new BencodeDecodeError('unexpected end of bencoded value');
  const code = bytes.codeAt(index);
  if (code === CODE_i) return decodeInt(bytes, index);
  if (code === CODE_l) return decodeList(bytes, index);
  if (code === CODE_d) return decodeDict(bytes, index);
  if (code >= CODE_ZERO && code <= CODE_NINE) return decodeByteString(bytes, index);
  throw new BencodeDecodeError('not a valid bencoded value');
}

/**
 * Decode a complete bencoded value.
 *
 * @param {ByteString|string|number[]} data
 * @returns {bigint|ByteString|Array|Map}
 */
export function decode(data) {
  const bytes = ByteString.coerce(data);
  if (bytes.length === 0) throw new BencodeDecodeError('cannot decode an empty value');
  const [value, next] = decodeValue(bytes, 0);
  if (next !== bytes.length) {
    throw new BencodeDecodeError('invalid bencoded value (data after valid prefix)');
  }
  return value;
}

