/**
 * Terminal width discovery, matching `shutil.get_terminal_size()`.
 *
 * `argparse`'s help formatter sizes itself to `get_terminal_size().columns - 2`,
 * so usage and help text wrap differently under a narrow terminal or an
 * explicit `COLUMNS` setting.  CPython resolves the width by consulting
 * `COLUMNS` first, then the terminal attached to *stdout* (even when the text
 * is destined for stderr), then the (80, 24) fallback used for pipes.
 */

import { tryPyInt } from '../python/int.mjs';

const FALLBACK_COLUMNS = 80;
const FALLBACK_LINES = 24;

/** `shutil.get_terminal_size()` as `{ columns, lines }`. */
export function getTerminalSize() {
  let columns = envInt('COLUMNS');
  let lines = envInt('LINES');

  if (columns <= 0 || lines <= 0) {
    const [ttyColumns, ttyLines] = stdoutSize();
    if (columns <= 0) columns = ttyColumns;
    if (lines <= 0) lines = ttyLines;
  }
  return { columns, lines };
}

/** `int(os.environ[name])`, or 0 when unset or not an integer. */
function envInt(name) {
  const raw = process.env[name];
  if (raw === undefined) return 0;
  const value = tryPyInt(raw);
  if (value === null) return 0;
  // Widths beyond a few thousand columns are clamped to a safe integer range.
  if (value > 1000000n) return 1000000;
  if (value < -1000000n) return -1000000;
  return Number(value);
}

/** Size of the terminal on stdout, or the pipe fallback. */
function stdoutSize() {
  const out = process.stdout;
  if (out && out.isTTY && Number.isInteger(out.columns) && out.columns > 0) {
    return [out.columns, Number.isInteger(out.rows) && out.rows > 0 ? out.rows : FALLBACK_LINES];
  }
  return [FALLBACK_COLUMNS, FALLBACK_LINES];
}

