/**
 * `textwrap.wrap()`, reduced to what `argparse`'s help formatter asks of it.
 *
 * The formatter always calls it as `textwrap.wrap(text, width)` on text whose
 * runs of whitespace have already been collapsed to single spaces, with the
 * default settings: greedy filling, breaking only at spaces, and splitting a
 * word that is by itself wider than the line.
 */

/** Collapse every whitespace run to one space and trim — `_whitespace_matcher`. */
export function normalizeWhitespace(text) {
  return text.replace(/[\t\n\v\f\r ]+/g, ' ').trim();
}

/**
 * Greedy word wrap.
 *
 * @param {string} text already whitespace-normalised
 * @param {number} width maximum line length, at least 1
 * @returns {string[]} lines, with no trailing whitespace and no empty entries
 */
export function wrapText(text, width) {
  const limit = Math.max(1, width);
  const lines = [];
  let current = '';

  for (const word of text.split(' ')) {
    if (word === '') continue;
    if (current === '') {
      current = word;
    } else if (current.length + 1 + word.length <= limit) {
      current += ` ${word}`;
    } else {
      lines.push(current);
      current = word;
    }
    // A single word longer than the line is chopped at the width, as
    // textwrap does with break_long_words left at its default.
    while (current.length > limit) {
      lines.push(current.slice(0, limit));
      current = current.slice(limit);
    }
  }
  if (current !== '') lines.push(current);
  return lines;
}

/** `textwrap.fill()`: wrap and join with newlines, prefixing every line. */
export function fillText(text, width, indent) {
  return wrapText(text, width)
    .map((line) => indent + line)
    .join('\n');
}

