/**
 * A port of `argparse.HelpFormatter`, covering the pieces this program's help
 * and error output actually exercise.
 *
 * Reproduced faithfully because both `--help` and every failure path print
 * through it: the `usage:` line (including its wrap behaviour when the terminal
 * is narrow), the `options:` section, the two-space gutter between an option
 * and its help text, and the exact column at which wrapped help resumes.
 *
 *     usage: test14_executable [-h] --a A --b B
 *
 *     options:
 *       -h, --help  show this help message and exit
 *       --a A
 *       --b B
 */

import { getTerminalSize } from './terminal.mjs';
import { normalizeWhitespace, wrapText } from './textwrap.mjs';

/** Sentinel matching `argparse.SUPPRESS`. */
export const SUPPRESS = '==SUPPRESS==';

function pad(width) {
  return ' '.repeat(Math.max(0, width));
}

function ljust(text, width) {
  return text.length >= width ? text : text + pad(width - text.length);
}

export class HelpFormatter {
  constructor({ prog, indentIncrement = 2, maxHelpPosition = 24, width = null } = {}) {
    this.prog = prog;
    this.indentIncrement = indentIncrement;
    // `argparse` derives the working width from the terminal, minus two.
    this.width = width === null ? getTerminalSize().columns - 2 : width;
    this.maxHelpPosition = Math.min(
      maxHelpPosition,
      Math.max(this.width - 20, indentIncrement * 2),
    );
    this.currentIndent = 0;
    this.actionMaxLength = 0;
  }

  indent() {
    this.currentIndent += this.indentIncrement;
  }

  dedent() {
    this.currentIndent -= this.indentIncrement;
  }

  /**
   * Record an action so the help column can be sized.  Mirrors
   * `add_argument`'s bookkeeping: invocation length plus the section indent.
   */
  addAction(action) {
    if (action.help === SUPPRESS) return;
    const length = this.formatActionInvocation(action).length + this.indentIncrement;
    this.actionMaxLength = Math.max(this.actionMaxLength, length);
  }

  /** `-h, --help` / `--a A` — how an option is labelled in the options list. */
  formatActionInvocation(action) {
    if (action.optionStrings.length === 0) {
      return this.metavarFor(action);
    }
    if (action.nargs === 0) {
      return action.optionStrings.join(', ');
    }
    const args = this.formatArgs(action);
    return action.optionStrings.map((optionString) => `${optionString} ${args}`).join(', ');
  }

  /** Default metavar: the destination upper-cased for options, as-is otherwise. */
  metavarFor(action) {
    if (action.metavar !== null && action.metavar !== undefined) return action.metavar;
    return action.optionStrings.length ? action.dest.toUpperCase() : action.dest;
  }

  /** The argument placeholder(s) that follow an option, e.g. `A`. */
  formatArgs(action) {
    const metavar = this.metavarFor(action);
    if (action.nargs === null || action.nargs === undefined) return metavar;
    if (action.nargs === '?') return `[${metavar}]`;
    if (action.nargs === '*') return `[${metavar} ...]`;
    if (action.nargs === '+') return `${metavar} [${metavar} ...]`;
    if (typeof action.nargs === 'number') return new Array(action.nargs).fill(metavar).join(' ');
    return metavar;
  }

  /** The bracketed usage fragment for one action. */
  usagePart(action) {
    if (action.help === SUPPRESS) return null;
    if (action.optionStrings.length === 0) return this.formatArgs(action);
    const optionString = action.optionStrings[0];
    const part = action.nargs === 0 ? optionString : `${optionString} ${this.formatArgs(action)}`;
    return action.required ? part : `[${part}]`;
  }

  usageParts(actions) {
    const parts = [];
    for (const action of actions) {
      const part = this.usagePart(action);
      if (part !== null) parts.push(part);
    }
    return parts;
  }

  /**
   * `usage: prog [-h] --a A --b B\n\n`, wrapped when it would overflow the
   * terminal.  When the program name alone eats more than three quarters of
   * the line, it goes on a line of its own and the options follow, indented to
   * the width of the `usage: ` prefix — which is what a narrow `COLUMNS` shows.
   */
  formatUsage(actions, prefix = 'usage: ') {
    const prog = this.prog;
    const optionals = actions.filter((action) => action.optionStrings.length > 0);
