/** Error types raised inside the argument parser. */

/**
 * `argparse.ArgumentError` — a problem attributable to one specific argument.
 *
 * Its string form is `argument <names>: <message>`, where `<names>` joins the
 * action's option strings with `/`, so `-h` and `--help` report together as
 * `argument -h/--help: ...`.
 */
export class ArgumentError extends Error {
  constructor(action, message) {
    super(ArgumentError.compose(action, message));
    this.name = 'ArgumentError';
    this.argumentName = ArgumentError.actionName(action);
    this.rawMessage = message;
  }

  /** `_get_action_name()`: option strings joined by `/`, else the metavar/dest. */
  static actionName(action) {
    if (!action) return null;
    if (action.optionStrings && action.optionStrings.length > 0) {
      return action.optionStrings.join('/');
    }
    if (action.metavar !== null && action.metavar !== undefined) return action.metavar;
    if (action.dest !== null && action.dest !== undefined) return action.dest;
    return null;
  }

  static compose(action, message) {
    const name = ArgumentError.actionName(action);
    return name === null ? String(message) : `argument ${name}: ${message}`;
  }
}

/** `argparse.ArgumentTypeError` — raised by a type callable to reject a value. */
export class ArgumentTypeError extends Error {
  constructor(message) {
    super(message);
    this.name = 'ArgumentTypeError';
  }
}

