/**
 * Type callables for `addArgument({ type })`.
 *
 * `argparse` reports a rejected value as
 *
 *     argument --a: invalid int value: '5.0'
 *
 * where `int` is the *name* of the type callable and the value is rendered with
 * Python's `repr()`.  Each callable therefore carries a `typeName`, and signals
 * rejection by throwing — the parser turns that into the message above.
 */

import { pyInt } from '../python/int.mjs';

/**
 * `type=int`: full CPython `int(str)` semantics, unbounded, returned as a
 * `BigInt` so arithmetic on the parsed values cannot lose precision.
 */
export const intType = Object.assign((text) => pyInt(text), { typeName: 'int' });

/** `type=str`: the identity conversion argparse uses by default. */
export const strType = Object.assign((text) => text, { typeName: 'str' });

/** `type=float`: accepts what Python's `float()` accepts. */
export const floatType = Object.assign((text) => {
  const normalized = text.trim();
  if (normalized === '' || !/^[+-]?(\d+\.?\d*|\.\d+)(e[+-]?\d+)?$|^[+-]?(inf(inity)?|nan)$/i.test(normalized)) {
    throw new TypeError(`could not convert string to float: '${text}'`);
  }
  return Number(normalized.replace(/^\+/, ''));
}, { typeName: 'float' });

