/**
 * A port of `argparse.ArgumentParser`, scoped to the option shapes this
 * program uses — long options that take exactly one value, plus the automatic
 * `-h/--help` — but faithful to CPython's algorithm inside that scope.
 *
 * The behaviours reproduced here are the ones a hand-rolled `process.argv` loop
 * gets wrong:
 *
 *   - `--a=5` and `--a 5` are equivalent; `--a=` yields an empty value that the
 *     type callable then rejects.
 *   - a repeated option keeps the last value (`--a 5 --a 7` -> 7).
 *   - `-5` is a value, not an option, because no option here looks like a
 *     negative number — and `\d` means any Unicode digit, so `-٥` is a value
 *     too, while `-5abc` and `-_10` are option-shaped and produce
 *     `expected one argument`.
 *   - long options may be abbreviated to any unambiguous prefix, so `--h`,
 *     `--he` and `--hel` all mean `--help`.
 *   - `--` ends option parsing, and cannot itself be swallowed as a value.
 *   - errors are ordered: an invalid value is reported as it is encountered,
 *     missing required options next, and unrecognised leftovers last.
 *   - failures print usage plus `prog: error: ...` to stderr and exit 2;
 *     `--help` prints to stdout and exits 0.
 */

import { HelpFormatter, SUPPRESS } from './formatter.mjs';
import { ArgumentError, ArgumentTypeError } from './errors.mjs';
import { strType } from './types.mjs';
import { SystemExit, writeOut, writeErr } from '../python/print.mjs';
import { reprStr } from '../python/repr.mjs';

export { SUPPRESS };

/**
 * `_negative_number_matcher`.  Python's `re` module resolves `\d` to the whole
 * Unicode decimal-digit category, so this deliberately uses `\p{Nd}` rather
 * than JavaScript's ASCII-only `\d`.
 */
const NEGATIVE_NUMBER_MATCHER = /^-\p{Nd}+$|^-\p{Nd}*\.\p{Nd}+$/u;

/** One parsed command-line option. */
class Action {
  constructor({
    optionStrings,
    dest,
    nargs = null,
    kind = 'store',
    type = null,
    required = false,
    help = null,
    metavar = null,
    defaultValue = null,
    constValue = null,
  }) {
    this.optionStrings = optionStrings;
    this.dest = dest;
    this.nargs = nargs;
    this.kind = kind;
    this.type = type;
    this.required = required;
