      if (!seenActions.has(action) && action.required) {
        missing.push(ArgumentError.actionName(action));
      }
    }
    if (missing.length > 0) {
      this.error(`the following arguments are required: ${missing.join(', ')}`);
    }

    return [namespace, extras];
  }

  /**
   * `_parse_optional()`: decide whether a token is an option and, if so, which.
   *
   * Returns `null` for a plain value, or `{action, optionString, sep,
   * explicitArg}` — with `action === null` standing for "option-shaped but
   * unknown".
   */
  _parseOptional(argString) {
    if (argString === '') return null;
    if (!this.prefixChars.includes(argString[0])) return null;
    if (this._optionStringActions.has(argString)) {
      return { action: this._optionStringActions.get(argString), optionString: argString, sep: null, explicitArg: null };
    }
    if (argString.length === 1) return null;

    const equals = argString.indexOf('=');
    if (equals !== -1) {
      const optionString = argString.slice(0, equals);
      const explicitArg = argString.slice(equals + 1);
      if (this._optionStringActions.has(optionString)) {
        return { action: this._optionStringActions.get(optionString), optionString, sep: '=', explicitArg };
      }
    }

    const tuples = this._getOptionTuples(argString);
    if (tuples.length > 1) {
      const matches = tuples.map((tuple) => tuple.optionString).join(', ');
      this.error(`ambiguous option: ${argString} could match ${matches}`);
    }
    if (tuples.length === 1) return tuples[0];

    // Looks like a negative number and no option could be one: it's a value.
    if (NEGATIVE_NUMBER_MATCHER.test(argString) && !this._hasNegativeNumberOptionals) return null;
    // Contains a space: it was meant to be a value.
    if (argString.includes(' ')) return null;

    return { action: null, optionString: argString, sep: null, explicitArg: null };
  }

  /** `_get_option_tuples()`: abbreviation and single-dash-tail candidates. */
  _getOptionTuples(optionString) {
    const result = [];
    const chars = this.prefixChars;

    if (optionString.length > 1 && chars.includes(optionString[1])) {
      if (!this.allowAbbrev) return result;
      const equals = optionString.indexOf('=');
      const optionPrefix = equals === -1 ? optionString : optionString.slice(0, equals);
      const sep = equals === -1 ? null : '=';
      const explicitArg = equals === -1 ? null : optionString.slice(equals + 1);
      for (const [candidate, action] of this._optionStringActions) {
        if (candidate.startsWith(optionPrefix)) {
          result.push({ action, optionString: candidate, sep, explicitArg });
        }
      }
      return result;
    }

    const shortOptionPrefix = optionString.slice(0, 2);
    const shortExplicitArg = optionString.slice(2);
    for (const [candidate, action] of this._optionStringActions) {
      if (candidate === shortOptionPrefix) {
        result.push({ action, optionString: candidate, sep: '', explicitArg: shortExplicitArg });
      } else if (this.allowAbbrev && candidate.startsWith(optionString)) {
        result.push({ action, optionString: candidate, sep: null, explicitArg: null });
      }
    }
    return result;
  }

  /**
   * `_match_argument()`: how many of the following tokens this option takes.
   *
   * The nargs pattern for an option never accepts the `--` marker, so
   * `--a -- 5` is an error rather than `a=5`.
   */
  _matchArgument(action, argStringsPattern) {
    const nargsPattern = nargsPatternFor(action);
    const match = new RegExp(`^${nargsPattern}`).exec(argStringsPattern);
    if (match === null) throw new ArgumentError(action, nargsErrorFor(action));
    return match[1].length;
  }

  /** `_get_values()`: convert the collected strings for one action. */
  _getValues(action, argStrings) {
    if (argStrings.length === 1 && (action.nargs === null || action.nargs === '?')) {
      return this._getValue(action, argStrings[0]);
    }
    return argStrings.map((argString) => this._getValue(action, argString));
  }

  /** `_get_value()`: run the type callable, turning refusal into a diagnostic. */
  _getValue(action, argString) {
    const typeFunc = action.type || strType;
    try {
      return typeFunc(argString);
    } catch (err) {
      if (err instanceof ArgumentTypeError) throw new ArgumentError(action, err.message);
      const typeName = typeFunc.typeName || typeFunc.name || 'value';
      throw new ArgumentError(action, `invalid ${typeName} value: ${reprStr(argString)}`);
    }
  }

  /** Apply an action's effect to the namespace. */
  _callAction(action, namespace, values, optionString) {
    switch (action.kind) {
      case 'help':
        this.printHelp();
        this.exit(0);
        break;
      case 'store_true':
        namespace[action.dest] = true;
        break;
      case 'store_false':
        namespace[action.dest] = false;
        break;
      case 'store_const':
        namespace[action.dest] = action.const;
        break;
      case 'append': {
        const existing = Array.isArray(namespace[action.dest]) ? namespace[action.dest] : [];
        namespace[action.dest] = [...existing, values];
        break;
      }
      case 'store':
      default:
        namespace[action.dest] = values;
        break;
    }
  }

  // --------------------------------------------------------------- messages

  _formatter() {
    const formatter = new HelpFormatter({ prog: this.prog });
    for (const action of this._actions) {
      formatter.indent();
      formatter.addAction(action);
      formatter.dedent();
    }
    return formatter;
  }

  /** `format_usage()`: the `usage:` block with one trailing newline. */
  formatUsage() {
    const formatter = this._formatter();
    return HelpFormatter.finalize(formatter.formatUsage(this._actions));
  }

  /** `format_help()`: usage, description, the options section, epilog. */
  formatHelp() {
    const formatter = this._formatter();
    const parts = [formatter.formatUsage(this._actions)];
    parts.push(formatter.formatText(this.description));
    // A parser with no positionals renders an empty `positional arguments`
    // section, which formats to nothing at all.
    parts.push(formatter.formatSection('positional arguments', this._actions.filter((a) => a.optionStrings.length === 0)));
    parts.push(formatter.formatSection('options', this._actions.filter((a) => a.optionStrings.length > 0)));
    parts.push(formatter.formatText(this.epilog));
    return HelpFormatter.finalize(parts.join(''));
  }

  printUsage(toStderr = false) {
    (toStderr ? writeErr : writeOut)(this.formatUsage());
  }

  printHelp(toStderr = false) {
    (toStderr ? writeErr : writeOut)(this.formatHelp());
  }

  /** `error()`: usage plus `prog: error: message` on stderr, then exit 2. */
  error(message) {
    this.printUsage(true);
    this.exit(2, `${this.prog}: error: ${message}\n`);
  }

  /** `exit()`: optionally print, then raise `SystemExit`. */
  exit(status = 0, message = null) {
    if (message) writeErr(message);
    throw new SystemExit(status);
  }
}

/** `'--a'` -> `'a'`, `'--foo-bar'` -> `'foo_bar'`, `'-x'` -> `'x'`. */
function deriveDest(optionStrings, prefixChars) {
  let candidate = null;
  for (const optionString of optionStrings) {
    if (optionString.length > 1 && prefixChars.includes(optionString[1])) {
      candidate = optionString;
      break;
    }
  }
  if (candidate === null) candidate = optionStrings[0];
  let dest = candidate;
  while (dest.length > 0 && prefixChars.includes(dest[0])) dest = dest.slice(1);
  return dest.replace(/-/g, '_');
}

/** `_get_nargs_pattern()`, with the `--`-rejecting adjustment for options. */
function nargsPatternFor(action) {
  const nargs = action.nargs;
  let pattern;
  if (nargs === null || nargs === undefined) pattern = '(-*A-*)';
  else if (nargs === '?') pattern = '(-*A?-*)';
  else if (nargs === '*') pattern = '(-*[A-]*)';
  else if (nargs === '+') pattern = '(-*A[A-]*)';
  else pattern = `(-*${new Array(nargs).fill('A').join('-*')}-*)`;

  if (action.optionStrings.length > 0) {
    pattern = pattern.split('-*').join('').split('-').join('');
  }
  return pattern;
}

/** The `_match_argument()` failure text for each nargs form. */
function nargsErrorFor(action) {
  const nargs = action.nargs;
  if (nargs === null || nargs === undefined) return 'expected one argument';
  if (nargs === '?') return 'expected at most one argument';
  if (nargs === '+') return 'expected at least one argument';
  return `expected ${nargs} argument${nargs === 1 ? '' : 's'}`;
}

/** `prog` defaults to `os.path.basename(sys.argv[0])`. */
function defaultProg() {
  const argv0 = process.argv[1] || '';
  const parts = argv0.split(/[\\/]/);
  return parts[parts.length - 1] || 'program';
}

