#!/usr/bin/env node
/**
 * Node.js port of dataset/bencoder/test14.py.
 *
 * The Python original:
 *
 *     import argparse
 *     import bencoder
 *
 *     parser = argparse.ArgumentParser()
 *     parser.add_argument('--a', type=int, required=True)
 *     parser.add_argument('--b', type=int, required=True)
 *     args = parser.parse_args()
 *
 *     numbers = [args.a, args.b, args.a + args.b, args.a * args.b]
 *     encoded = bencoder.encode(numbers)          # Encode list of numbers
 *     decoded = bencoder.decode(encoded)          # Decode numbers
 *     encoded_negative = bencoder.encode(-args.a) # Encode negative number
 *     encoded_zero = bencoder.encode(0)           # Encode zero
 *     print(encoded)
 *     print(decoded)
 *     print(encoded_negative)
 *     print(encoded_zero)
 *
 * Two things drive the design of the library behind this file:
 *
 *   - Python integers are unbounded, and `a * b` overflows a double as soon as
 *     the inputs pass ~9e7 each, so every value is carried as a `BigInt`
 *     end to end.  `--a 99999999999999999999999999 --b 99999999999999999999999999`
 *     must print all 52 digits of the product, exactly.
 *   - `print()` of a `bytes` object emits its `repr()`, so the output lines are
 *     `b'...'` literals rather than raw bytes.
 */

import { ArgumentParser } from './lib/cli/argparse.mjs';
import { intType } from './lib/cli/types.mjs';
import * as bencoder from './lib/bencode/index.mjs';
import { pyPrint, SystemExit } from './lib/python/print.mjs';

/**
 * `prog` as the reference build reports it, so the `usage:` line and the
 * `prog: error: ...` diagnostics match it character for character rather than
 * naming this script.
 */
const PROG = 'test14_executable';

/** The parser from the Python source: two required integer options. */
export function buildParser() {
  const parser = new ArgumentParser({ prog: PROG });
  parser.addArgument('--a', { type: intType, required: true });
  parser.addArgument('--b', { type: intType, required: true });
  return parser;
}

/** Run the program body; returns the process exit status. */
export function main(argv = process.argv.slice(2)) {
  const args = buildParser().parseArgs(argv);

  const numbers = [args.a, args.b, args.a + args.b, args.a * args.b];
  const encoded = bencoder.encode(numbers); // Encode list of numbers
  const decoded = bencoder.decode(encoded); // Decode numbers
  const encodedNegative = bencoder.encode(-args.a); // Encode negative number
  const encodedZero = bencoder.encode(0n); // Encode zero
  pyPrint(encoded);
  pyPrint(decoded);
  pyPrint(encodedNegative);
  pyPrint(encodedZero);
  return 0;
}

try {
  process.exitCode = main();
} catch (error) {
  // `argparse` signals `--help` and every usage failure by raising SystemExit;
  // setting exitCode rather than calling process.exit() lets Node flush stdout
  // and stderr first, which matters when the output is piped.
  if (error instanceof SystemExit) process.exitCode = error.code;
  else throw error;
}

