 *
 * `int(s)` runs the string through `_PyUnicode_TransformDecimalAndSpaceToASCII`
 * before parsing it.  That transform only rewrites code points at or above 127:
 * those get folded to a plain space when `Py_UNICODE_ISSPACE()` holds, or to an
 * ASCII digit when they are decimal digits.  Everything below 127 is passed
 * through untouched and then judged by the ASCII-only `Py_ISSPACE()`.
 *
 * The observable consequence is that the four C0 separators U+001C..U+001F are
 * whitespace to `str.strip()` but *not* to `int()`, so `int('\x1c5')` raises
 * while `int('\x855')` and `int('\xa05')` both return 5.
 */
export function isIntLiteralWhitespace(codePoint) {
  if (codePoint < 127) {
    // Py_ISSPACE: space, tab, newline, vertical tab, form feed, carriage return.
    return codePoint === 0x20 || (codePoint >= 0x09 && codePoint <= 0x0d);
  }
  return PY_WHITESPACE.has(codePoint);
}

